# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""Out-of-place scalar foreach subtract (`aten::_foreach_sub.Scalar`) in Triton.

Semantics reproduced from the native reference (verified on the target):
  out_i = self_i - scalar          (fresh storage, never aliasing self)
  * output dtype == input dtype for floating inputs;
  * int32 + integer scalar -> int32, int32 + float scalar -> default float dtype;
  * other input dtypes raise RuntimeError; an empty tensor list raises
    RuntimeError.

Dense tensors (contiguous or permuted/transposed views, recognised by folding
the shape/stride pairs into one contiguous run) are streamed in storage order
with an output that keeps the input's strides, so reads and writes are both
sequential.  All dense tensors of one call that share device, dtype, compute
mode and scalar kind are packed into a single prefix-range launch (up to
_BATCH tensors per launch): a program maps its global block index to exactly
one tensor, which removes per-launch dispatch cost for short foreach lists
without wasting programs on unequal lengths.  Non-dense views (gaps, stride 0)
take a strided gather kernel that writes a contiguous output.

The launch grid is capped at a validated block count and each program strides
by `tl.num_programs(0)`: on this target one-block-per-program launches with
262144 blocks fault (AIV exception) for a 1e9-element tensor, while the same
work in a capped grid-stride loop is correct.
"""

import torch
import triton
import triton.language as tl

_BLOCK = 4096
_BLOCK_HALF = 8192
_MAX_BLOCKS = 4096
_BATCH_BLOCK_LIMIT = 8 * _MAX_BLOCKS
_MAX_RANK = 4
_BATCH = 4
_SUPPORTED = (torch.float16, torch.bfloat16, torch.float32, torch.float64, torch.int32)


@triton.jit
def _blk(
    x_ptr,
    y_ptr,
    n,
    s,
    b,
    BLOCK: tl.constexpr,
    FP32_OP: tl.constexpr,
    MASKED: tl.constexpr,
):
    """One BLOCK of one tensor, flat storage offsets."""
    offs = b * BLOCK + tl.arange(0, BLOCK)
    if MASKED:
        mask = offs < n
        x = tl.load(x_ptr + offs, mask=mask, other=0)
    else:
        x = tl.load(x_ptr + offs)
    if FP32_OP:
        y = x.to(tl.float32) - s
    else:
        y = x - s
    if MASKED:
        tl.store(y_ptr + offs, y, mask=mask)
    else:
        tl.store(y_ptr + offs, y)


@triton.jit
def _sub_flat_kernel(
    x_ptr, y_ptr, n, s, BLOCK: tl.constexpr, FP32_OP: tl.constexpr, MASKED: tl.constexpr
):
    pid = tl.program_id(0)
    npr = tl.num_programs(0)
    nblk = tl.cdiv(n, BLOCK)
    for b in range(pid, nblk, npr):
        _blk(x_ptr, y_ptr, n, s, b, BLOCK, FP32_OP, MASKED)


@triton.jit
def _sub_batch4(
    x0,
    y0,
    n0,
    s0,
    x1,
    y1,
    n1,
    s1,
    x2,
    y2,
    n2,
    s2,
    x3,
    y3,
    n3,
    s3,
    k1,
    k2,
    k3,
    nb,
    NC: tl.constexpr,
    BLOCK: tl.constexpr,
    FP32_OP: tl.constexpr,
    MASKED: tl.constexpr,
):
    """One launch for NC dense tensors: global block g belongs to the tensor
    whose [k_i, k_i+1) block range contains it."""
    pid = tl.program_id(0)
    npr = tl.num_programs(0)
    if NC == 2:
        for g in range(pid, nb, npr):
            if g < k1:
                _blk(x0, y0, n0, s0, g, BLOCK, FP32_OP, MASKED)
            else:
                _blk(x1, y1, n1, s1, g - k1, BLOCK, FP32_OP, MASKED)
    elif NC == 3:
        for g in range(pid, nb, npr):
            if g < k1:
                _blk(x0, y0, n0, s0, g, BLOCK, FP32_OP, MASKED)
            elif g < k2:
                _blk(x1, y1, n1, s1, g - k1, BLOCK, FP32_OP, MASKED)
            else:
                _blk(x2, y2, n2, s2, g - k2, BLOCK, FP32_OP, MASKED)
    else:
        for g in range(pid, nb, npr):
            if g < k1:
                _blk(x0, y0, n0, s0, g, BLOCK, FP32_OP, MASKED)
            elif g < k2:
                _blk(x1, y1, n1, s1, g - k1, BLOCK, FP32_OP, MASKED)
            elif g < k3:
                _blk(x2, y2, n2, s2, g - k2, BLOCK, FP32_OP, MASKED)
            else:
                _blk(x3, y3, n3, s3, g - k3, BLOCK, FP32_OP, MASKED)


@triton.jit
def _sub_strided_kernel(
    x_ptr,
    y_ptr,
    n,
    s0,
    s1,
    s2,
    s3,
    t0,
    t1,
    t2,
    t3,
    s,
    BLOCK: tl.constexpr,
    FP32_OP: tl.constexpr,
):
    pid = tl.program_id(0)
    npr = tl.num_programs(0)
    nblk = tl.cdiv(n, BLOCK)
    for b in range(pid, nblk, npr):
        idx = b * BLOCK + tl.arange(0, BLOCK)
        mask = idx < n
        q0 = s1 * s2 * s3
        i0 = idx // q0
        rem = idx % q0
        q1 = s2 * s3
        i1 = rem // q1
        rem = rem % q1
        i2 = rem // s3
        i3 = rem % s3
        off = i0 * t0 + i1 * t1 + i2 * t2 + i3 * t3
        x = tl.load(x_ptr + off, mask=mask, other=0)
        if FP32_OP:
            y = x.to(tl.float32) - s
        else:
            y = x - s
        tl.store(y_ptr + idx, y, mask=mask)


def _grid(n, blk=_BLOCK):
    return (min(triton.cdiv(n, blk), _MAX_BLOCKS),)


def _block_for(dtype, max_numel):
    """Width-scaled block size, never larger than needed for the data.

    Two-byte element types use twice the element count so each iteration moves
    the same bytes per direction as fp32; a group whose largest tensor is
    smaller than the cap keeps the smaller block so no vector lane is masked
    off.
    """
    cap = _BLOCK_HALF if dtype.itemsize <= 2 else _BLOCK
    blk = 1024
    while blk < cap and blk < max_numel:
        blk *= 2
    return blk


def _merged_dims(t):
    """(size, stride) pairs sorted by decreasing stride, merged when dense."""
    dims = [(sh, st) for sh, st in zip(t.shape, t.stride()) if sh != 1]
    dims = sorted(dims, key=lambda p: -p[1])
    merged = []
    for sh, st in dims:
        if merged and merged[-1][1] == st * sh:
            # adjacent in memory: the pair collapses onto the inner stride
            psh, _ = merged[-1]
            merged[-1] = (psh * sh, st)
        else:
            merged.append((sh, st))
    return merged


def _is_dense(merged):
    return len(merged) <= 1 and (not merged or merged[0][1] == 1)


def _scalar_args(t, scalar):
    """(output dtype, fp32 compute flag, kernel scalar argument)."""
    dt = t.dtype
    if dt not in _SUPPORTED:
        raise RuntimeError("input must be half, float, int32 or bfloat16")
    if dt.is_floating_point:
        return dt, dt in (torch.float16, torch.bfloat16), float(scalar)
    if isinstance(scalar, bool):
        scalar = int(scalar)
    if isinstance(scalar, int) or (isinstance(scalar, float) and scalar.is_integer()):
        return torch.int32, False, int(scalar)
    return torch.get_default_dtype(), True, float(scalar)


def _write_strided(t, out, sarg, fp32_op):
    """Gather-style path for non-dense views; out must be contiguous."""
    n = t.numel()
    if n == 0:
        return
    merged = _merged_dims(t)
    if len(merged) <= _MAX_RANK:
        pad = _MAX_RANK - len(merged)
        shp = [1] * pad + [p[0] for p in merged]
        strd = [0] * pad + [p[1] for p in merged]
        _sub_strided_kernel[_grid(n)](
            t,
            out,
            n,
            shp[0],
            shp[1],
            shp[2],
            shp[3],
            strd[0],
            strd[1],
            strd[2],
            strd[3],
            sarg,
            BLOCK=_BLOCK,
            FP32_OP=fp32_op,
        )
        return
    # Deep fallback for exotic ranks: walk the outermost dimension with
    # zero-copy views on both sides so every launch sees rank <= 4.
    for i in range(t.shape[0]):
        _write_strided(t.select(0, i), out.select(0, i), sarg, fp32_op)


def _launch_dense(items, fp32_op):
    """Launch a group of dense (device, dtype, scalar-kind) tensors.

    items entries are (tensor, out, scalar_arg, fp32_op, numel).  A single
    prefix-range launch is used only while the group's total block count stays
    small: for half precision a long grid-stride loop exposes a fixed
    per-iteration load-pipe latency that 8 KB/direction of traffic cannot hide
    (measured 11% MTE2 idle at 256 iterations per program), so big groups fall
    back to the branch-free per-tensor kernel.
    """
    for c in range(0, len(items), _BATCH):
        chunk = items[c : c + _BATCH]
        max_numel = 0
        for it in chunk:
            if it[4] > max_numel:
                max_numel = it[4]
        blk = _block_for(chunk[0][0].dtype, max_numel)
        masked = False
        for it in chunk:
            if it[4] % blk:
                masked = True
        nb = 0
        for it in chunk:
            nb += -(-it[4] // blk)
        if len(chunk) == 1 or nb > _BATCH_BLOCK_LIMIT:
            for t, out, sarg, _, n in chunk:
                _sub_flat_kernel[_grid(n, blk)](
                    t, out, n, sarg, BLOCK=blk, FP32_OP=fp32_op, MASKED=masked
                )
            continue
        m = len(chunk)
        fill_t = chunk[0][0]
        fill_s = 0 if isinstance(chunk[0][2], int) else 0.0
        args = []
        starts = []
        blocks = 0
        for j in range(_BATCH):
            starts.append(blocks)
            if j < m:
                t, out, sarg, _, n = chunk[j]
                args.extend((t, out, n, sarg))
                blocks += -(-n // blk)
            else:
                args.extend((fill_t, fill_t, 0, fill_s))
        _sub_batch4[(min(blocks, _MAX_BLOCKS),)](
            *args,
            starts[1],
            starts[2],
            starts[3],
            blocks,
            NC=m,
            BLOCK=blk,
            FP32_OP=fp32_op,
            MASKED=masked,
        )


def foreach_sub_scalar(self, scalar):
    tensors = [self] if torch.is_tensor(self) else list(self)
    if not tensors:
        raise RuntimeError("Tensor list must have at least one tensor.")
    count = len(tensors)
    if isinstance(scalar, (list, tuple)):
        if len(scalar) != count:
            raise RuntimeError("scalar list length must match the tensor list length")
        scalars = list(scalar)
    else:
        scalars = None

    outs = [None] * count
    dense = []
    for i, t in enumerate(tensors):
        out_dtype, fp32_op, sarg = _scalar_args(
            t, scalar if scalars is None else scalars[i]
        )
        n = t.numel()
        if t.is_contiguous():
            if out_dtype == t.dtype:
                out = torch.empty_like(t)
            else:
                out = torch.empty(t.size(), dtype=out_dtype, device=t.device)
        elif _is_dense(_merged_dims(t)):
            out = torch.empty_strided(
                t.size(), t.stride(), dtype=out_dtype, device=t.device
            )
        else:
            out = torch.empty(t.size(), dtype=out_dtype, device=t.device)
            outs[i] = out
            _write_strided(t, out, sarg, fp32_op)
            continue
        outs[i] = out
        if n:
            dense.append((t, out, sarg, fp32_op, n))

    if dense:
        groups = {}
        for item in dense:
            t = item[0]
            key = (t.device, t.dtype, item[3], isinstance(item[2], int))
            groups.setdefault(key, []).append(item)
        for items in groups.values():
            _launch_dense(items, items[0][3])
    return outs
